// tiny speed-correction model (9-8-1 tanh MLP), trained on 19533 windows from ProcTHOR houses 20-43 (ignored features: [])
// output: log(true window displacement / assumed-depth measurement); input normalisation folded into the first layer
#pragma once
#define SNN_H 8
static const double SNN_W1[9 * SNN_H] = {-0.248605286, 0.250219943, 0.315313331, 0.187928465, -0.18390555, -0.362680302, 0.792554895, 0.363130371, 0.244822959, -0.0903881286, -0.458470599, -0.254788219, -0.453957307, -0.0453737055, -0.196849527, -0.0685110664, -0.599075804, -0.557338586, 0.838312912, -0.135496537, 1.10204405, 2.02371572, -0.590242393, -1.18533322, 0.161118271, -0.0904311696, -4.07036341, -0.31565428, -1.02725121, 0.210321426, -0.626727848, 0.267671857, 0.0388271114, -0.0552987098, 0.142532197, -0.117502926, -0.658764879, 0.252158072, 0.757923997, 0.923119218, -1.13025366, 0.331085878, 0.838838889, 0.0144486918, 0.291400668, -0.111601393, 0.671103469, 0.0717618471, 7.20116889, 4.36368352, 0.888465048, -0.626530148, 2.06883942, 1.08626405, -6.14642884, -1.63872224, 0.472581824, 0.150358275, -0.251589606, -0.174281079, -0.222972196, -0.321966547, 0.115331627, -0.079446711, 0.705148569, -1.10016029, 0.867012882, 0.341093187, -0.161601241, -0.701433523, -0.478753044, 0.0657743091};
static const double SNN_B1[SNN_H] = {-0.680212952, 1.59722011, 0.19110021, 0.421022161, -0.875983186, -0.928407657, 3.8609459, 1.5492222};
static const double SNN_W2[SNN_H] = {0.249969688, -0.275258798, 0.253591294, -0.156428957, -0.34573801, 0.391516289, -0.488405595, 0.424385777};
static const double SNN_B2 = 0.07860772;
static inline double speednn_eval(const double* x) {
    double y = SNN_B2;
    for (int j = 0; j < SNN_H; j++) {
        double a = SNN_B1[j];
        for (int i = 0; i < 9; i++) a += SNN_W1[i * SNN_H + j] * x[i];
        y += SNN_W2[j] * std::tanh(a);
    }
    return y;
}
